1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.regex.Pattern;
6	
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
10	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
11	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
12	import org.springframework.web.bind.annotation.RequestBody;
13	
14	/**
15	 * Binds the owner body and rejects it when any required field is missing or blank, so an
16	 * invalid body is a 400 (listing the offending field names) even when the owner does not exist.
17	 * Also normalizes the telephone to E.164 form (see {@link TelephoneE164}), publishing the
18	 * normalized value so it is stored and returned as {@code telephone}.
19	 * The address is normalized (see {@link AddressNormalizer}) before the required-field check, so a
20	 * value that is blank only after normalization is rejected, and the normalized form is stored and
21	 * returned as {@code address}.
22	 * The optional email is accepted when absent; when present it must be a syntactically valid
23	 * address (else 400) and is lower-cased so it is stored and returned as {@code email}.
24	 * Runs before {@link LoadOwner}/{@link BuildOwner} and publishes the body for later steps.
25	 */
26	public class ValidateOwner {
27	
28	    /** Syntactic email check: a non-empty local part, an '@', then a dotted domain. */
29	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+$");
30	
31	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
32	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
33	        List<String> missing = new ArrayList<>();
34	        if (isBlank(request.getFirstName())) {
35	            missing.add("firstName");
36	        }
37	        if (isBlank(request.getLastName())) {
38	            missing.add("lastName");
39	        }
40	        // Normalize the address before the required-field check, so an address that is blank
41	        // only after normalization is rejected, and the normalized value is stored and returned.
42	        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
43	        if (isBlank(request.getAddress())) {
44	            missing.add("address");
45	        }
46	        if (isBlank(request.getCity())) {
47	            missing.add("city");
48	        }
49	        if (isBlank(request.getTelephone())) {
50	            missing.add("telephone");
51	        }
52	        if (!missing.isEmpty()) {
53	            throw new MissingOwnerFieldsException(missing);
54	        }
55	        // Normalize telephone to E.164; reject anything that cannot form a valid number.
56	        String e164 = TelephoneE164.normalize(request.getTelephone());
57	        if (e164 == null) {
58	            throw new InvalidTelephoneException(request.getTelephone());
59	        }
60	        request.setTelephone(e164);
61	        // Email is optional. When present it must be syntactically valid; store it lower-cased.
62	        String email = request.getEmail();
63	        if (email != null && !email.isBlank()) {
64	            String normalized = email.trim().toLowerCase();
65	            if (!EMAIL.matcher(normalized).matches()) {
66	                throw new InvalidEmailException(email);
67	            }
68	            request.setEmail(normalized);
69	        }
70	        validated.set(request);
71	    }
72	
73	    private static boolean isBlank(String value) {
74	        return value == null || value.isBlank();
75	    }
76	}
