1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Assigns the owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>} where
11	 * CITY3 is the upper-cased first three letters of the city, LAST3 the upper-cased first three
12	 * letters of the last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more
13	 * than the number of owners already in that city (e.g. {@code SYD-SMI-0007}).
14	 */
15	public class AssignCustomerCode {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String cityPrefix = prefix(owner.getCity());
19	        String lastNamePrefix = prefix(owner.getLastName());
20	        String city = normalize(owner.getCity());
21	        int sequence = 1;
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (city.equals(normalize(existing.getCity()))) {
24	                sequence++;
25	            }
26	        }
27	        owner.setCustomerCode(String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence));
28	    }
29	
30	    /** Upper-cased first three letters of {@code value}. */
31	    private static String prefix(String value) {
32	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
33	    }
34	
35	    /** Lower-cases and trims so the city comparison ignores case and surrounding whitespace. */
36	    private static String normalize(String value) {
37	        if (value == null) {
38	            return "";
39	        }
40	        return value.trim().toLowerCase(Locale.ROOT);
41	    }
42	}
