3	/**
4	 * Thrown by {@link org.springframework.samples.petclinic.rest.function.owner.CheckDailyLimit}
5	 * when {@value org.springframework.samples.petclinic.rest.function.owner.CheckDailyLimit#MAX_PER_DAY}
6	 * or more owners have already been created today (by registrationDate), so no further owner may be
7	 * created until tomorrow. Handled globally by {@link DailyLimitExceededExceptionHandler}, which
8	 * responds 429.
9	 */
10	public class DailyLimitExceededException extends Exception {
11	
12	    private final int count;
13	
14	    public DailyLimitExceededException(int count) {
15	        super("Daily owner creation limit reached (" + count + " owners created today)");
16	        this.count = count;
17	    }
18	
19	    public int getCount() {
20	        return this.count;
21	    }
22	}
