		assertTrue(dow != DayOfWeek.SATURDAY && dow != DayOfWeek.SUNDAY, dow.toString());
	}

	/** business-day: a registration date SUPPLIED in the request that falls on a weekend is rolled
	 * forward to the following Monday too. Uses a fixed Saturday (not a pinned holiday) so the
	 * expected Monday is deterministic regardless of the run date. */
	@Test
	void suppliedWeekendDateRollsToMonday() throws Exception {
		ObjectNode o = ownerNode();
		o.put("registrationDate", "2026-08-15"); // a Saturday
		int id = createOwnerOk(o);
		assertEquals("2026-08-17", fetchOwner(id).get("registrationDate").asText());
	}

	/** business-day: a registration date supplied on a business day is stored unchanged. */
	@Test
	void suppliedBusinessDayDateIsUnchanged() throws Exception {
		ObjectNode o = ownerNode();
		o.put("registrationDate", "2026-08-17"); // a Monday
		int id = createOwnerOk(o);
		assertEquals("2026-08-17", fetchOwner(id).get("registrationDate").asText());
	}
}

